(4, 395, 'chuks okonta', 'nordichuks@gmail.com', 'http://www.afrihoster.com', '197.210.85.184', '2019-12-10 06:49:07', '2019-12-10 06:49:07', 'Interesting article about Christmas where God turned enemies to become friends on Christmas day ..British and German Army. As we celebrate Christmas may God touch the minds of Nigeria Elites to build this country of ours call Nigeria.', 0, '1', 'Mozilla/5.0 (Linux; Android 8.1.0; TECNO LB7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/78.0.3904.108 Mobile Safari/537.36', 'comment', 0, 0),
(5, 395, 'Chris O. O. Biose', 'Chrisoobiose@gmail.com', 'http://WWW.BOLDTIMES.COM.NG', '105.112.23.76', '2019-12-17 12:50:47', '2019-12-17 12:50:47', 'thank you very much, be blessed', 0, '1', 'Mozilla/5.0 (Windows NT 6.3; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/79.0.3945.79 Safari/537.36', 'comment', 4, 1),
(6, 408, 'chuks okonta', 'nordichuks@gmail.com', 'http://www.afrihoster.com', '197.210.84.151', '2019-12-28 17:13:49', '2019-12-28 17:13:49', 'Interesting article, keep it up, the country needs the likes of Dora A. May God help us.', 0, '1', 'Mozilla/5.0 (Linux; Android 8.1.0; TECNO LB7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/78.0.3904.108 Mobile Safari/537.36', 'comment', 0, 0),
(12, 431, 'chuks okonta', 'nordichuks@gmail.com', 'http://www.afrihoster.com', '197.210.85.66', '2020-08-06 14:27:06', '2020-08-06 14:27:06', 'Very nice letter, up Anioma nation.', 0, '1', 'Mozilla/5.0 (Linux; Android 8.1.0; TECNO LB7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4103.106 Mobile Safari/537.36', 'comment', 0, 0),
(412, 341, 'boldtimesmanager', 'admin@boldtimes.com.ng', 'https://boldtimes.net.ng', '197.210.79.200', '2023-06-02 05:34:51', '2023-06-02 05:34:51', 'Call 08077960629 for the book', 0, '1', 'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/111.0.0.0 Mobile Safari/537.36', 'comment', 370, 1),
