(1, 1, 'lsoxta-ibouxj-ovedmi-fgyldo-xnqpsg', 7, 1, 'jcqzmd-lfqwtx-vxcylr-noxlev-wckzpi', 'admin@boldtimes.com.ng', 'Sent', '', 0, NULL, '2022-11-01 08:33:20', '0000-00-00 00:00:00'),
(2, 1, 'lsoxta-ibouxj-ovedmi-fgyldo-xnqpsg', 7, 2, 'gompyk-umxdfk-dgmihl-jidbrv-eonusl', 'chrisoobiose@gmail.com', 'Sent', '', 0, NULL, '2022-11-01 08:33:20', '0000-00-00 00:00:00');
INSERT INTO `wp5g_ig_workflows` (`id`, `name`, `title`, `trigger_name`, `trigger_options`, `rules`, `actions`, `status`, `type`, `priority`, `meta`, `created_at`, `updated_at`) VALUES
(1, 'send-welcome-email-when-someone-subscribes', 'Send welcome email when someone subscribes', 'ig_es_user_subscribed', '', '', 'a:1:{i:0;a:5:{s:11:\"action_name\";s:16:\"ig_es_send_email\";s:13:\"ig-es-send-to\";s:9:\"{{EMAIL}}\";s:19:\"ig-es-email-subject\";s:23:\"Welcome to {{SITENAME}}\";s:19:\"ig-es-email-content\";s:189:\"<p>Hi {{NAME}},</p>\n<p>Just wanted to send you a quick note...</p>\n<p>Thank you for joining the awesome {{SITENAME}} tribe.</p>\n<p>Only valuable emails from me, promise!</p>\n<p>Thanks!</p>\n\";s:26:\"ig-es-tracking-campaign-id\";i:2;}}', 1, 1, 0, 'a:2:{s:11:\"when_to_run\";s:11:\"immediately\";s:11:\"last_ran_at\";s:19:\"2023-05-05 10:10:50\";}', '2022-11-01 08:33:18', '2022-11-01 08:33:18'),
(2, 'send-confirmation-email', 'Send confirmation email', 'ig_es_user_unconfirmed', '', '', 'a:1:{i:0;a:5:{s:11:\"action_name\";s:16:\"ig_es_send_email\";s:13:\"ig-es-send-to\";s:9:\"{{EMAIL}}\";s:19:\"ig-es-email-subject\";s:7:\"Thanks!\";s:19:\"ig-es-email-content\";s:210:\"<p>Hi {{NAME}},</p>\n<p>Just one more step before we share the awesomeness from {{SITENAME}}!</p>\n<p>Please confirm your subscription by clicking on <a href=\'{{SUBSCRIBE-LINK}}\'>this link</a></p>\n<p>Thanks!</p>\n\";s:26:\"ig-es-tracking-campaign-id\";i:4;}}', 1, 1, 0, 'a:2:{s:11:\"when_to_run\";s:11:\"immediately\";s:11:\"last_ran_at\";s:19:\"2026-02-27 01:27:04\";}', '2022-11-01 08:33:18', '2022-11-01 08:33:18'),
(3, 'notify-admin-when-someone-subscribes', 'Notify admin when someone subscribes', 'ig_es_user_subscribed', '', '', 'a:1:{i:0;a:5:{s:11:\"action_name\";s:16:\"ig_es_send_email\";s:13:\"ig-es-send-to\";s:22:\"admin@boldtimes.com.ng\";s:19:\"ig-es-email-subject\";s:33:\"One more contact joins our tribe!\";s:19:\"ig-es-email-content\";s:282:\"<p>Hi,</p>\n<p>Your friendly Email Subscribers notification bot here!</p>\n<p>{{NAME}} ({{EMAIL}}) joined our tribe just now.</p>\n<p>Which list/s? {{LIST}}</p>\n<p>If you know this person, or if they are an influencer, you may want to reach out to them personally!</p>\n<p>Later...</p>\n\";s:26:\"ig-es-tracking-campaign-id\";i:5;}}', 1, 1, 0, 'a:2:{s:11:\"when_to_run\";s:11:\"immediately\";s:11:\"last_ran_at\";s:19:\"2023-05-05 10:10:50\";}', '2022-11-01 08:33:18', '2022-11-01 08:33:18'),
(4, 'notify-admin-when-campaign-is-sent', 'Notify admin when campaign is sent', 'ig_es_campaign_sent', '', '', 'a:1:{i:0;a:5:{s:11:\"action_name\";s:16:\"ig_es_send_email\";s:13:\"ig-es-send-to\";s:22:\"admin@boldtimes.com.ng\";s:19:\"ig-es-email-subject\";s:14:\"Campaign Sent!\";s:19:\"ig-es-email-content\";s:180:\"<p>Hi Admin,</p>\n<p>Cron URL has been triggered successfully on {{DATE}} for the email \'{{SUBJECT}}\'. And it sent email to {{COUNT}} recipient(s).</p>\n<p>Best,<br />\nBoldTimes</p>\n\";s:26:\"ig-es-tracking-campaign-id\";i:6;}}', 1, 1, 0, 'a:1:{s:11:\"when_to_run\";s:11:\"immediately\";}', '2022-11-01 08:33:18', '2022-11-01 08:33:18'),
(5, 'add-to-main-list-when-someone-registers', 'Add to Main list when someone registers', 'ig_es_user_registered', '', '', 'a:1:{i:0;a:2:{s:11:\"action_name\";s:17:\"ig_es_add_to_list\";s:10:\"ig-es-list\";i:2;}}', 0, 0, 0, 'a:1:{s:11:\"when_to_run\";s:11:\"immediately\";}', '2022-11-01 08:33:18', '0000-00-00 00:00:00');
