(405, 1, '2019-12-14 08:10:47', '2019-12-14 08:10:47', '<!-- wp:pdfemb/pdf-embedder-viewer {\"pdfID\":406,\"url\":\"https://boldtimes.net.ng-content/uploads/2019/12/A-MESSAGE-OF-CHRISTMAS.pdf\",\"toolbarfixed\":\"on\"} -->\n<p class=\"wp-block-pdfemb-pdf-embedder-viewer\"></p>\n<!-- /wp:pdfemb/pdf-embedder-viewer -->', 'A MESSAGE for CHRISTMAS', '', 'publish', 'open', 'closed', '', 'a-message-for-christmas-2', '', '', '2022-11-29 09:41:48', '2022-11-29 09:41:48', '<!-- wp:pdfemb/pdf-embedder-viewer {\"pdfID\":406,\"url\":\"https://boldtimes.net.ng-content/uploads/2019/12/A-MESSAGE-OF-CHRISTMAS.pdf\",\"toolbarfixed\":\"on\"} -->\n<p class=\"wp-block-pdfemb-pdf-embedder-viewer\"></p>\n<!-- /wp:pdfemb/pdf-embedder-viewer -->', 0, 'https://boldtimes.com.ng/?p=405', 0, 'post', '', 0),
